//! `sermofur_core::scope_policy` against the table that the .NET `ScopePolicy` produced
//! (`rust/tests/golden/scope-policy.json`, regenerated by `rust/tools/scope-oracle`): crafted
//! and random trees, written with their answers.

use serde_json::{Value, json};
use sermofur_core::error::SermofurError;
use sermofur_core::scope_policy::{ScopeLike, expected_parent, validate_tree, visible_ancestors};

/// A scope of the table: the kind is the .NET value, possibly undefined.
struct Stored {
    id: String,
    kind: i64,
    parent_id: Option<String>,
    relative_path: Option<String>,
}

impl ScopeLike for Stored {
    fn id(&self) -> &str {
        &self.id
    }
    fn kind_value(&self) -> i64 {
        self.kind
    }
    fn parent_id(&self) -> Option<&str> {
        self.parent_id.as_deref()
    }
    fn relative_path(&self) -> Option<&str> {
        self.relative_path.as_deref()
    }
}

fn error(e: &SermofurError) -> Value {
    // ToDictionary throws ArgumentException; the CLI answers invalid_storage_or_path.
    if e.code == "invalid_storage_or_path" {
        json!({ "exception": "System.ArgumentException" })
    } else {
        json!({ "code": e.code, "message": e.message, "exitCode": e.exit_code })
    }
}

#[test]
fn scope_policy_matches_the_oracle() {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../tests/golden/scope-policy.json"
    );
    let golden: Value =
        serde_json::from_str(&std::fs::read_to_string(path).expect("golden file")).expect("JSON");
    let mut mismatches = Vec::new();
    for row in golden["expectedParent"].as_array().expect("rows") {
        let kind = row["kind"].as_i64().expect("kind");
        let actual = match expected_parent(kind) {
            Ok(parent) => {
                json!({ "visible": parent.map(|p| vec![p.to_string()]).unwrap_or_default() })
            }
            Err(e) => error(&e),
        };
        if actual != row["expected"] {
            mismatches.push(format!(
                "ExpectedParent({kind}): expected {}, got {actual}",
                row["expected"]
            ));
        }
    }
    let trees = golden["trees"].as_array().expect("trees");
    assert!(trees.len() > 300, "crafted and random trees");
    for tree in trees {
        let name = tree["name"].as_str().expect("name");
        let text = |v: &Value| v.as_str().map(str::to_owned);
        let scopes: Vec<Stored> = tree["scopes"]
            .as_array()
            .expect("scopes")
            .iter()
            .map(|s| Stored {
                id: s["id"].as_str().expect("id").to_owned(),
                kind: s["kind"].as_i64().expect("kind"),
                parent_id: text(&s["parentId"]),
                relative_path: text(&s["relativePath"]),
            })
            .collect();
        let validate = match validate_tree(&scopes) {
            Ok(()) => json!({ "ok": true }),
            Err(e) => error(&e),
        };
        if validate != tree["validate"] {
            mismatches.push(format!(
                "{name} ValidateTree: expected {}, got {validate}",
                tree["validate"]
            ));
        }
        for (id, expected) in tree["visibleAncestors"].as_object().expect("visible") {
            let actual = match visible_ancestors(id, &scopes) {
                Ok(set) => {
                    let mut ids: Vec<String> = set.into_iter().collect();
                    // Ordinal order, as the oracle sorts.
                    ids.sort_by(|a, b| a.encode_utf16().cmp(b.encode_utf16()));
                    json!({ "visible": ids })
                }
                Err(e) => error(&e),
            };
            if &actual != expected {
                mismatches.push(format!(
                    "{name} VisibleAncestors({id}): expected {expected}, got {actual}"
                ));
            }
        }
    }
    assert!(mismatches.is_empty(), "{}", mismatches.join("\n"));
}
